package reconstruct

import (
	"context"
	"testing"

	"github.com/bnb-chain/tss-lib/v2/eddsa/keygen"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"

	"github.com/nsuiteio/nsuite-mpc-key-export/utility/keyutil"
	"github.com/nsuiteio/nsuite-mpc-key-export/utility/strutil"
)

func TestReconstructEdDSA(t *testing.T) {
	ctx := context.Background()

	testCases := []struct {
		threshold   int
		localShares []string
		expected    string
	}{
		{
			threshold: 1,
			localShares: []string{
				"",
				"",
			},
			expected: "0x01cabefc8055e12e9337c8a57dd3967d45e61a84020aa58d7c209f035873f667",
		},
		{
			threshold: 3,
			localShares: []string{
				"",
				"",
				"",
			},
			expected: "0x08314f94a480690ae6819cd3b8a8cd44938ea6f34f17d8b5929688087eb6c909",
		},
	}

	for _, tc := range testCases {
		t.Run(
			"", func(t *testing.T) {
				shares := make(
					[]*keygen.LocalPartySaveData,
					len(tc.localShares),
				)
				for i, shareHex := range tc.localShares {
					shareBs, err := strutil.FromHex(shareHex)
					require.NoError(t, err)
					share, err := keyutil.LocalDataFromBytesEdDSA(ctx, shareBs)
					require.NoError(t, err)
					shares[i] = share
				}
				prvKey, err := ReconstructEdDSA(ctx, tc.threshold, shares)
				require.NoError(t, err)
				prvStr := strutil.ToHex(prvKey.Serialize())
				assert.Equal(t, tc.expected, prvStr)
			},
		)
	}
}
